"use strict";
const fs = require("node:fs");
const path = require("node:path");
const generatedMarkers = ["GENERATED by tools/projection", "GENERATED by tools/src/projection", "Code generated by tools/src/projection"];
function determineImplementationOrigin(obligation) {
    const repositoryRoot = process.cwd();
    const manifestPath = path.join(repositoryRoot, "languages", obligation.language, "conformance", `${obligation.binding.implementationId}.conformance.json`);
    if (!fs.existsSync(manifestPath))
        return { origin: "UNKNOWN", reason: "no conformance manifest found" };
    const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
    let projectedCount = 0;
    let handWrittenCount = 0;
    for (const semanticObject of manifest.semanticObjects ?? []) {
        const sourceRef = semanticObject.embodiment?.sourceRef;
        if (!sourceRef)
            continue;
        const sourcePath = path.join(repositoryRoot, sourceRef);
        if (!fs.existsSync(sourcePath))
            continue;
        const content = fs.readFileSync(sourcePath, "utf8");
        if (generatedMarkers.some((marker) => content.includes(marker)))
            projectedCount += 1;
        else
            handWrittenCount += 1;
    }
    if (projectedCount === 0 && handWrittenCount === 0) {
        return { origin: "UNKNOWN", reason: "no semanticObjects entry declares a resolvable embodiment.sourceRef" };
    }
    return {
        origin: projectedCount > 0 && handWrittenCount > 0 ? "MIXED" : projectedCount > 0 ? "PROJECTED" : "HAND_AUTHORED",
        projectedCount,
        handWrittenCount
    };
}
module.exports = { determineImplementationOrigin };
